import string

def censor_words(text, forbidden_words):
    if not text or not forbidden_words:
        return text
    forbidden_set = {w.lower() for w in forbidden_words}
    tokens = text.split(" ")
    result = []
    for token in tokens:
        i = 0
        while i < len(token) and token[i] in string.punctuation:
            i += 1
        j = len(token)
        while j > i and token[j - 1] in string.punctuation:
            j -= 1
        prefix = token[:i]
        core = token[i:j]
        suffix = token[j:]
        if core.lower() in forbidden_set:
            result.append(prefix + ("*" * len(core)) + suffix)
        else:
            result.append(token)
    return " ".join(result)
